// CSD_RATIONALE_BEGIN
// Diagnosis of previous attempts:
//   Attempt 33 (best syntax 95.9%, accuracy 4.1%): CloseSpanIfComplete in the inner
//   loop closes at the FIRST complete parser state (e.g. a single variable name),
//   producing trivially correct syntax but semantically empty expressions. 45/49 were
//   syntax-valid but wrong.
//
//   Attempt 36 (accuracy 12.2%, syntax 40.8%): The 8-token warmup pushed the model past
//   short complete states (better accuracy) but the uncapped ConstrainedStep loop
//   produced repetition loops ("n0*r*d + n0*r*d - n0*r*d …") BEFORE
//   CloseSpanWithinBudget was called, resulting in 13 unclosed and 11 malformed spans.
//
// Root causes:
//   1. CloseSpanIfComplete: closes at trivially short complete expressions → wrong answers.
//   2. Uncapped ConstrainedStep warmup: repetition loop degrades currentConstrained
//      before CloseSpanWithinBudget can find a good closing point.
//   3. Large CloseSpanWithinBudget budget (800+): allows excessively long/repetitive
//      expressions to be selected as "longest complete prefix".
//
// Fix strategy:
//   A. Replace CloseSpanIfComplete in the inner loop entirely. Instead:
//      - Use a TINY warmup (3 ConstrainedSteps) to ensure we're past trivial
//        one-token complete states.
//      - Immediately call CloseSpanWithinBudget with a CAPPED budget of 80 tokens.
//        This lets the helper find the longest complete prefix in a bounded window,
//        preventing both premature closure and runaway repetition.
//   B. After Phase 1 (UnconstrainedChunk up to 65% budget), try:
//      Phase 2: warmup(3) + CloseSpanWithinBudget(80)
//      Phase 3: RenderedEndsWith fallback for 80 free steps
//      Phase 4: warmup(3) + CloseSpanWithinBudget(80) for Phase 3 span
//      Phase 5: force OpenConstrainedSpan + warmup(3) + CloseSpanWithinBudget(remaining)
//      Final:   safety CloseSpanWithinBudget with any remaining budget
//   C. Guidance: no <<, >>, or LaTeX. Plain text "The answer is EXPR" instruction.
//   D. Budget accounting: 65%*900 + 3 + 80 + 80 + 3 + 80 + 1 + 3 + remaining ≤ 900.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (UnconstrainedChunk): insideConstrainedOut stays false throughout Phase 1.
//     On stoppedOnOpen, EnterObservedConstrainedSpan sets currentConstrainedOut := []
//     which satisfies IsValidPrefix([]) by precondition. ✓
//
//   Phase 2a / 4a / 5a (warmup ConstrainedStep loops): ConstrainedStep hard-masks to
//     parser-valid tokens plus EOS; AppendConstrainedToken's postcondition gives
//     IsValidPrefix(currentConstrainedOut ++ [next]). EOS path breaks without
//     appending, leaving state unchanged. ✓
//
//   Phase 2b / 4b / 5b / final (CloseSpanWithinBudget): library postcondition
//     guarantees insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
//   Phase 3 (UnconstrainedStep + RenderedEndsWith): insideConstrainedOut stays false
//     until RenderedEndsWith("<<"); then EnterObservedConstrainedSpan sets
//     currentConstrainedOut := [] (valid). ✓
//
//   Phase 5 open (OpenConstrainedSpan): sets currentConstrainedOut := [] (valid). ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//   Phase 1: UnconstrainedChunk postcondition |generatedOut| <= |generated_old| + su;
//     steps += su. EnterObservedConstrainedSpan adds 0 tokens, 0 steps. ✓
//   Phase 2a/4a/5a warmup: each iteration steps += 1; AppendConstrainedToken
//     extends generated by exactly 1 token; EOS appends 0. ✓
//   Phase 2b/4b/5b/final: CloseSpanWithinBudget postcondition
//     |generatedOut| <= |generated_old| + budget; steps += budget. ✓
//   Phase 3: UnconstrainedStep steps += 1, generated grows by at most 1. ✓
//   Phase 5 open: OpenConstrainedSpan appends "<<" (1 token), steps += 1. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Reason step by step. At the end write: The answer is EXPR where EXPR uses only variable names from the problem without curly braces, numbers, +, -, *, /, (, ), int(). Use int() for truncating fractions, for example int(n * frac). No LaTeX, no dollar signs, no backslashes, no curly braces in EXPR.");

var steps: nat := 0;
var hasCompletedSpan: bool := false;

// Phase 1 budget: 65% of maxSteps
var phase1Limit: nat := (maxSteps * 65) / 100;
if phase1Limit == 0 && maxSteps > 0 { phase1Limit := 1; }

// Phase 3 limit: phase1Limit + 80 extra free steps
var phase3Limit: nat := phase1Limit + 80;
if phase3Limit > maxSteps { phase3Limit := maxSteps; }

// ── Phase 1: Free chunks watching for "<<" ──────────────────────────────────
while steps < phase1Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Limit - steps
{
  var chunkSz: nat := 40;
  if steps + chunkSz > phase1Limit { chunkSz := phase1Limit - steps; }
  if chunkSz == 0 { break; }
  var cg, soo, soe, su := helpers.UnconstrainedChunk(lm, prompt, generated, chunkSz, "<<", eosToken);
  generated := cg;
  steps := steps + su;
  if soe { break; }
  if soo {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg; insideConstrainedOut := ei; currentConstrainedOut := ec;
  }
}

// ── Phase 2a: 3-token warmup (prevents premature closure at single-token states) ──
var warmup1: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && warmup1 < 3
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  invariant warmup1 <= 3
  decreases 3 - warmup1
{
  var cp1 := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next1 := helpers.ConstrainedStep(lm, parser, cp1, currentConstrainedOut, eosToken);
  steps := steps + 1;
  warmup1 := warmup1 + 1;
  if next1 == eosToken { break; }
  var ag1, ai1, ac1 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next1);
  generated := ag1; insideConstrainedOut := ai1; currentConstrainedOut := ac1;
}

// ── Phase 2b: Close with CAPPED budget (80 steps) ───────────────────────────
if insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  var bud1: nat := 80;
  if steps + bud1 > maxSteps { bud1 := maxSteps - steps; }
  if bud1 > 0 {
    var wg1, wi1, wc1 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud1);
    generated := wg1; insideConstrainedOut := wi1; currentConstrainedOut := wc1;
    steps := steps + bud1;
    if !insideConstrainedOut { hasCompletedSpan := true; }
  }
}

// ── Phase 3: More free gen if no span detected yet (RenderedEndsWith) ────────
while steps < phase3Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase3Limit - steps
{
  var next3 := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next3 == eosToken { break; }
  generated := generated + [next3];
  if RenderedEndsWith(generated, "<<") {
    var eg3, ei3, ec3 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg3; insideConstrainedOut := ei3; currentConstrainedOut := ec3;
  }
}

// ── Phase 4a: Warmup for span from Phase 3 ───────────────────────────────────
var warmup2: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && warmup2 < 3
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  invariant warmup2 <= 3
  decreases 3 - warmup2
{
  var cp2 := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next2 := helpers.ConstrainedStep(lm, parser, cp2, currentConstrainedOut, eosToken);
  steps := steps + 1;
  warmup2 := warmup2 + 1;
  if next2 == eosToken { break; }
  var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next2);
  generated := ag2; insideConstrainedOut := ai2; currentConstrainedOut := ac2;
}

// ── Phase 4b: Close with capped budget ───────────────────────────────────────
if insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  var bud2: nat := 80;
  if steps + bud2 > maxSteps { bud2 := maxSteps - steps; }
  if bud2 > 0 {
    var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud2);
    generated := wg2; insideConstrainedOut := wi2; currentConstrainedOut := wc2;
    steps := steps + bud2;
    if !insideConstrainedOut { hasCompletedSpan := true; }
  }
}

// ── Phase 5: Force open if no span completed yet ─────────────────────────────
if !insideConstrainedOut && !hasCompletedSpan && steps + 1 < maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg; insideConstrainedOut := fi; currentConstrainedOut := fc;
  steps := steps + 1;

  // Phase 5a: Warmup 3 tokens
  var warmup3: nat := 0;
  while insideConstrainedOut && steps < maxSteps && warmup3 < 3
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    invariant warmup3 <= 3
    decreases 3 - warmup3
  {
    var cp5 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next5 := helpers.ConstrainedStep(lm, parser, cp5, currentConstrainedOut, eosToken);
    steps := steps + 1;
    warmup3 := warmup3 + 1;
    if next5 == eosToken { break; }
    var ag5, ai5, ac5 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next5);
    generated := ag5; insideConstrainedOut := ai5; currentConstrainedOut := ac5;
  }

  // Phase 5b: Close with ALL remaining budget (forced open, so we must close)
  if insideConstrainedOut && steps < maxSteps {
    var bud5 := maxSteps - steps;
    if bud5 > 0 {
      var wg5, wi5, wc5 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud5);
      generated := wg5; insideConstrainedOut := wi5; currentConstrainedOut := wc5;
      steps := steps + bud5;
    }
  }
}

// ── Final safety close ────────────────────────────────────────────────────────
if insideConstrainedOut && steps < maxSteps {
  var bud6 := maxSteps - steps;
  if bud6 > 0 {
    var wg6, wi6, wc6 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud6);
    generated := wg6; insideConstrainedOut := wi6; currentConstrainedOut := wc6;
    steps := steps + bud6;
  }
}

