    steps := steps + bud1;
    if !insideConstrainedOut { hasCompletedSpan := true; }
  }
}

// ── Phase 3: More free gen if no span detected yet (RenderedEndsWith) ────────
while steps < phase3Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase3Limit - steps
{
  var next3 := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next3 == eosToken { break; }
  generated := generated + [next3];
  if RenderedEndsWith(generated, "<<") {
    var eg3, ei3, ec3 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg3; insideConstrainedOut := ei3; currentConstrainedOut := ec3;
  }
}

// ── Phase 4a: Warmup for span from Phase 3 ───────────────────────────────────
var warmup2: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && warmup2 < 3
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  invariant warmup2 <= 3
  decreases 3 - warmup2
{
  var cp2 := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next2 := helpers.ConstrainedStep(lm, parser, cp2, currentConstrainedOut, eosToken);
  steps := steps + 1;
  warmup2 := warmup2 + 1;
  if next2 == eosToken { break; }
  var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next2);
  generated := ag2; insideConstrainedOut := ai2; currentConstrainedOut := ac2;
}

// ── Phase 4b: Close with capped budget ───────────────────────────────────────
if insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  var bud2: nat := 80;
  if steps + bud2 > maxSteps { bud2 := maxSteps - steps; }
  if bud2 > 0 {
    var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud2);
    generated := wg2; insideConstrainedOut := wi2; currentConstrainedOut := wc2;
    steps := steps + bud2;
    if !insideConstrainedOut { hasCompletedSpan := true; }
  }
}

// ── Phase 5: Force open if no span completed yet ─────────────────────────────
if !insideConstrainedOut && !hasCompletedSpan && steps + 1 < maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg; insideConstrainedOut := fi; currentConstrainedOut := fc;
  steps := steps + 1;

  // Phase 5a: Warmup 3 tokens
  var warmup3: nat := 0;
  while insideConstrainedOut && steps < maxSteps && warmup3 < 3
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    invariant warmup3 <= 3
    decreases 3 - warmup3
  {
    var cp5 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next5 := helpers.ConstrainedStep(lm, parser, cp5, currentConstrainedOut, eosToken);
    steps := steps + 1;
    warmup3 := warmup3 + 1;
    if next5 == eosToken { break; }
    var ag5, ai5, ac5 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next5);
    generated := ag5; insideConstrainedOut := ai5; currentConstrainedOut := ac5;
  }

  // Phase 5b: Close with ALL remaining budget (forced open, so we must close)
  if insideConstrainedOut && steps < maxSteps {
    var bud5 := maxSteps - steps;
    if bud5 > 0 {
      var wg5, wi5, wc5 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud5);
      generated := wg5; insideConstrainedOut := wi5; currentConstrainedOut := wc5;
      steps := steps + bud5;
    }
  }
}

// ── Final safety close ────────────────────────────────────────────────────────
if insideConstrainedOut && steps < maxSteps {
  var bud6 := maxSteps - steps;
  if bud6 > 0 {
    var wg6, wi6, wc6 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud6);
    generated := wg6; insideConstrainedOut := wi6; currentConstrainedOut := wc6;
    steps := steps + bud6;
  }
}

cost := steps;
